program test_fortad_fortsym_equivalence
    !! fortad's products against fortsym's, for every operator that ships both.
    !!
    !! fortfem's production derivative kernels are generated symbolically. This
    !! checks that the fortad path is an alternative and not a variant: for the
    !! same primal, at the same point, both products must agree to rounding.
    !!
    !! The adjoint identity is checked as well. Agreement with fortsym alone
    !! would pass if a wrong extraction made both fortad products consistently
    !! wrong in the same way; the identity relates the two to each other and
    !! uses no generator at all.
    !!
    !! Generated by tools/fortad/emit.py. The calls differ per operator - the
    !! two generators order their arguments differently - and forty-four pairs
    !! written by hand would be forty-four chances to get an order wrong and
    !! have the test pass anyway on a symmetric point.
    use, intrinsic :: iso_fortran_env, only: dp => real64
    use fortfem_generated_block_graph_product_jvp, only: generated_block_graph_product_jvp
    use fortfem_generated_block_graph_product_vjp, only: generated_block_graph_product_vjp
    use fortfem_fortad_block_graph_product_jvp, only: fortfem_block_graph_product_jvp_fortad
    use fortfem_fortad_block_graph_product_vjp, only: fortfem_block_graph_product_vjp_fortad
    use fortfem_generated_cgl_pressure_divergence_jvp, only: generated_cgl_pressure_divergence_jvp
    use fortfem_generated_cgl_pressure_divergence_vjp, only: generated_cgl_pressure_divergence_vjp
    use fortfem_fortad_cgl_pressure_divergence_jvp, only: fortfem_cgl_pressure_divergence_jvp_fortad
    use fortfem_fortad_cgl_pressure_divergence_vjp, only: fortfem_cgl_pressure_divergence_vjp_fortad
    use fortfem_generated_cgl_pressure_tensor_jvp, only: generated_cgl_pressure_tensor_jvp
    use fortfem_generated_cgl_pressure_tensor_vjp, only: generated_cgl_pressure_tensor_vjp
    use fortfem_fortad_cgl_pressure_tensor_jvp, only: fortfem_cgl_pressure_tensor_jvp_fortad
    use fortfem_fortad_cgl_pressure_tensor_vjp, only: fortfem_cgl_pressure_tensor_vjp_fortad
    use fortfem_generated_fci_cubic_bezier_edge_area_jvp, only: generated_fci_cubic_bezier_edge_area_jvp
    use fortfem_generated_fci_cubic_bezier_edge_area_vjp, only: generated_fci_cubic_bezier_edge_area_vjp
