    use fortfem_generated_cartesian_to_toroidal_vjp, only: generated_cartesian_to_toroidal_vjp
    use fortfem_fortad_cartesian_to_toroidal_jvp, only: fortfem_cartesian_to_toroidal_jvp_fortad
    use fortfem_fortad_cartesian_to_toroidal_vjp, only: fortfem_cartesian_to_toroidal_vjp_fortad
    use fortfem_generated_toroidal_coordinates_jvp, only: generated_toroidal_point_to_cartesian_jvp
    use fortfem_generated_toroidal_coordinates_vjp, only: generated_toroidal_point_to_cartesian_vjp
    use fortfem_fortad_toroidal_point_to_cartesian_jvp, only: fortfem_toroidal_point_to_cartesian_jvp_fortad
    use fortfem_fortad_toroidal_point_to_cartesian_vjp, only: fortfem_toroidal_point_to_cartesian_vjp_fortad
    use fortfem_generated_toroidal_vector_to_cartesian_jvp, only: generated_toroidal_vector_to_cartesian_jvp
    use fortfem_generated_toroidal_vector_to_cartesian_vjp, only: generated_toroidal_vector_to_cartesian_vjp
    use fortfem_fortad_toroidal_vector_to_cartesian_jvp, only: fortfem_toroidal_vector_to_cartesian_jvp_fortad
    use fortfem_fortad_toroidal_vector_to_cartesian_vjp, only: fortfem_toroidal_vector_to_cartesian_vjp_fortad
    use fortfem_generated_toroidal_poisson_products_jvp, only: generated_toroidal_poisson_products_jvp
    use fortfem_generated_toroidal_poisson_products_vjp, only: generated_toroidal_poisson_products_vjp
    use fortfem_fortad_toroidal_poisson_products_jvp, only: fortfem_toroidal_poisson_products_jvp_fortad
    use fortfem_fortad_toroidal_poisson_products_vjp, only: fortfem_toroidal_poisson_products_vjp_fortad
    use fortfem_generated_torus_curved_panel_jvp, only: generated_torus_curved_panel_jvp
    use fortfem_generated_torus_curved_panel_vjp, only: generated_torus_curved_panel_vjp
    use fortfem_fortad_torus_curved_panel_jvp, only: fortfem_torus_curved_panel_jvp_fortad
    use fortfem_fortad_torus_curved_panel_vjp, only: fortfem_torus_curved_panel_vjp_fortad
    implicit none

    !! The two kernels evaluate the same expression in a different order, so
    !! they disagree in the last digits and the tolerance has to allow for it.
    !! Everything agrees to twelve digits or better except the degree-ten and
    !! degree-eleven Bezier edge areas, whose adjoints are long alternating
    !! sums.
    !!
    !! Those two get a looser bound, and it is loose because of the arithmetic
    !! rather than to make the test pass. Measured on the hendecic case at the
    !! test point: fortsym gives 0.118986354, fortad 0.118986349, and central
    !! differences of the primal 0.119015604 - the two engines are equidistant
    !! from the difference quotient, 2.92e-5 each, so neither is the outlier.
    !! Recompiling the fortsym kernel at -O2 moves its own answer in the eighth
    !! digit. The expression has lost those digits to cancellation before
    !! either engine is involved.
    real(dp), parameter :: TOLERANCE = 1.0e-8_dp
    !! For the two whose conditioning is the limit, not the differentiation.
    real(dp), parameter :: CANCELLING_TOLERANCE = 1.0e-6_dp
    integer :: failures

    failures = 0
    ! block_graph_product
    block
        real(dp) :: v_block_value
        real(dp) :: v_state_value
        real(dp) :: v_contribution
        real(dp) :: d_block_value
        real(dp) :: gr_block_value
        real(dp) :: gn_block_value
        real(dp) :: d_state_value
        real(dp) :: gr_state_value
        real(dp) :: gn_state_value
        real(dp) :: tr_contribution
        real(dp) :: tn_contribution
        real(dp) :: seed_contribution
        call fill_point(v_block_value, 1)
        call fill_point(v_state_value, 2)
