                  tr_tangent_xi_2, tn_tangent_xi_2, TOLERANCE, failures)
        call same("torus_curved_panel jvp tangent_xi_3", &
                  tr_tangent_xi_3, tn_tangent_xi_3, TOLERANCE, failures)
        call same("torus_curved_panel jvp tangent_eta_1", &
                  tr_tangent_eta_1, tn_tangent_eta_1, TOLERANCE, failures)
        call same("torus_curved_panel jvp tangent_eta_2", &
                  tr_tangent_eta_2, tn_tangent_eta_2, TOLERANCE, failures)
        call same("torus_curved_panel jvp tangent_eta_3", &
                  tr_tangent_eta_3, tn_tangent_eta_3, TOLERANCE, failures)
        call same("torus_curved_panel jvp surface_jacobian", &
                  tr_surface_jacobian, tn_surface_jacobian, TOLERANCE, failures)
        call generated_torus_curved_panel_vjp(v_parameter_11, v_parameter_21, &
            v_parameter_12, v_parameter_22, v_parameter_13, v_parameter_23, &
            v_major_radius, v_minor_radius, v_xi, v_eta, seed_point_1, &
            seed_point_2, seed_point_3, seed_tangent_xi_1, seed_tangent_xi_2, &
            seed_tangent_xi_3, seed_tangent_eta_1, seed_tangent_eta_2, &
            seed_tangent_eta_3, seed_surface_jacobian, gr_parameter_11, &
            gr_parameter_21, gr_parameter_12, gr_parameter_22, gr_parameter_13, &
            gr_parameter_23, gr_major_radius, gr_minor_radius, gr_xi, gr_eta)
        call fortfem_torus_curved_panel_vjp_fortad(v_parameter_11, &
            v_parameter_21, v_parameter_12, v_parameter_22, v_parameter_13, &
            v_parameter_23, v_major_radius, v_minor_radius, v_xi, v_eta, &
            v_point_2, v_point_3, v_tangent_xi_1, v_tangent_xi_2, v_tangent_xi_3, &
            v_tangent_eta_1, v_tangent_eta_2, v_tangent_eta_3, &
            v_surface_jacobian, seed_point_1, gn_parameter_11, gn_parameter_21, &
            gn_parameter_12, gn_parameter_22, gn_parameter_13, gn_parameter_23, &
            gn_major_radius, gn_minor_radius, gn_xi, gn_eta)
        call same("torus_curved_panel vjp parameter_11", &
                  gr_parameter_11, gn_parameter_11, TOLERANCE, failures)
        call same("torus_curved_panel vjp parameter_21", &
                  gr_parameter_21, gn_parameter_21, TOLERANCE, failures)
        call same("torus_curved_panel vjp parameter_12", &
                  gr_parameter_12, gn_parameter_12, TOLERANCE, failures)
        call same("torus_curved_panel vjp parameter_22", &
                  gr_parameter_22, gn_parameter_22, TOLERANCE, failures)
        call same("torus_curved_panel vjp parameter_13", &
                  gr_parameter_13, gn_parameter_13, TOLERANCE, failures)
        call same("torus_curved_panel vjp parameter_23", &
                  gr_parameter_23, gn_parameter_23, TOLERANCE, failures)
        call same("torus_curved_panel vjp major_radius", &
                  gr_major_radius, gn_major_radius, TOLERANCE, failures)
        call same("torus_curved_panel vjp minor_radius", &
                  gr_minor_radius, gn_minor_radius, TOLERANCE, failures)
        call same("torus_curved_panel vjp xi", &
                  gr_xi, gn_xi, TOLERANCE, failures)
        call same("torus_curved_panel vjp eta", &
                  gr_eta, gn_eta, TOLERANCE, failures)
    end block

    if (failures == 0) then
        print *, "test_fortad_fortsym_equivalence: all cases passed"
    else
        print *, "test_fortad_fortsym_equivalence: ", failures, " case(s) FAILED"
        error stop 1
    end if

contains

    elemental subroutine fill_point(value, k)
        !! A fixed, spread-out point. Deterministic on purpose: a failure has to
        !! be reproducible without recording a seed. Elemental so an argument
        !! declared as an array is filled without the caller knowing its shape.
        real(dp), intent(out) :: value
        integer, intent(in) :: k

        value = 0.6_dp + 0.35_dp*sin(1.7_dp*k) + 0.05_dp*k
    end subroutine fill_point

    elemental subroutine fill_direction(value, k)
        real(dp), intent(out) :: value
        integer, intent(in) :: k

        value = cos(0.9_dp*k) - 0.15_dp
    end subroutine fill_direction

    subroutine same(label, reference, produced, tolerance, failures)
        !! Agreement to rounding, entry by entry. The two kernels evaluate the
        !! same expression in a different order, so they are not bit-identical.
        !! Elemental arguments are compared as arrays so an operator with an
        !! array-shaped output is checked in every element rather than in a
        !! contraction that could hide a misplaced one.
        character(*), intent(in) :: label
        real(dp), intent(in) :: reference(..), produced(..)
        real(dp), intent(in) :: tolerance
        integer, intent(inout) :: failures

        select rank (reference)
        rank (0)
            select rank (produced)
            rank (0)
                call one(label, reference, produced, tolerance, failures)
            end select
        rank (1)
            select rank (produced)
            rank (1)
                call many(label, reference, produced, tolerance, failures)
            end select
        end select
    end subroutine same

    subroutine one(label, reference, produced, tolerance, failures)
        character(*), intent(in) :: label
        real(dp), intent(in) :: reference, produced, tolerance
        integer, intent(inout) :: failures

        if (abs(produced - reference) > tolerance*max(1.0_dp, abs(reference))) then
            print *, "FAIL ", label, ": ", reference, " vs ", produced
            failures = failures + 1
        else
            print *, "pass ", label
        end if
    end subroutine one

    subroutine many(label, reference, produced, tolerance, failures)
        character(*), intent(in) :: label
        real(dp), intent(in) :: reference(:), produced(:), tolerance
        integer, intent(inout) :: failures
        integer :: i
        logical :: bad

        bad = .false.
        do i = 1, size(reference)
            if (abs(produced(i) - reference(i)) > &
                tolerance*max(1.0_dp, abs(reference(i)))) then
                print *, "FAIL ", label, " entry ", i, ": ", reference(i), &
                    " vs ", produced(i)
                bad = .true.
            end if
        end do
        if (bad) then
            failures = failures + 1
        else
            print *, "pass ", label
        end if
    end subroutine many

end program test_fortad_fortsym_equivalence
